import type { ReportData } from '@pretoscop/report';

/**
 * Reports on the public site (M23). Only reports a founder approved with
 * `pnpm --filter @pretoscop/worker report:approve` are listed here (that command writes the JSON
 * next to this file and the block below); planned reports show a placeholder with the method.
 */
// <published:start> (generated by report:approve — do not edit by hand)
export const PUBLISHED: ReportData[] = [];
// <published:end>

export interface PlannedReport {
  id: string;
  title: string;
  expected: string;
  summary: string;
}

export const PLANNED: PlannedReport[] = [
  {
    id: 'black-friday-2026',
    title: 'Black Friday 2026: cât de reale au fost reducerile',
    expected: 'decembrie 2026',
    summary:
      'Comparăm prețul din zilele de Black Friday cu cel mai mic preț observat de Pretoscop la același magazin în cele 30 de zile dinainte, pentru fiecare ofertă pe care o urmărim din octombrie 2026.',
  },
];

export function findReport(id: string): ReportData | undefined {
  return PUBLISHED.find((r) => r.id === id && r.approval.approved);
}
